/* ---------- widget: excess and deficiency (Mg + 2HCl) ---------- */
function onTheory(root){const w=root.querySelector('#w-ex');if(!w)return;
  w.innerHTML=`<div class="small" style="text-align:center">Mg + 2HCl → MgCl₂ + H₂↑</div><label>m(Mg) = <output id="o1">4,8</output> г<input type="range" id="a" min="0" max="12" step="0.6" value="4.8"></label>
<label>m(HCl) = <output id="o2">7,3</output> г<input type="range" id="b" min="0" max="29.2" step="1.46" value="7.3"></label><div id="wS" style="display:flex;justify-content:center"></div><div id="wO" class="small" style="text-align:center"></div>`;
  const q=s=>w.querySelector(s);
  const draw=()=>{const ma=+q('#a').value,mb=+q('#b').value;q('#o1').textContent=N(rd(ma,2));q('#o2').textContent=N(rd(mb,2));
    const na=ma/24,nb=mb/36.5;const ext=Math.min(na,nb/2);const W=320,bw=200,sc=bw/0.5;let s='';
    const bar=(y,lab,have,need,col)=>T(8,y+15,lab,{a:'start',fs:13})+`<rect x="100" y="${y}" width="${Math.min(bw,have*sc).toFixed(1)}" height="20" fill="${col}" fill-opacity=".55"/><rect x="100" y="${y}" width="${Math.min(bw,need*sc).toFixed(1)}" height="20" fill="none" stroke="var(--fig)" stroke-width="2"/>`+T(100+Math.min(bw,Math.max(have,need)*sc)+6,y+15,N(rd(have,3))+' моль',{a:'start',fs:12,fw:400});
    s+=bar(10,'Mg',na,ext,'var(--accent)')+bar(40,'HCl',nb,2*ext,'var(--hl)')+bar(70,'H₂ (продукт)',ext,ext,'var(--ok)');
    s+=T(8,112,'рамка — сколько израсходуется',{a:'start',fs:11,fw:400,c:'var(--muted)'});
    q('#wS').innerHTML=SV(W,120,s,'Избыток и недостаток');
    const lim=na===0&&nb===0?'—':Math.abs(na-nb/2)<1e-9?'вещества в точном соотношении':na<nb/2?'Mg в недостатке, HCl в избытке':'HCl в недостатке, Mg в избытке';
    q('#wO').innerHTML=`n(Mg)/1 = ${N(rd(na,3))}, n(HCl)/2 = ${N(rd(nb/2,3))} → <span class="out">${lim}</span>. V(H₂) = ${N(rd(ext,3))} · 22,4 ≈ <span class="out">${N(rd(ext*22.4,2))} л</span>`;};
  w.querySelectorAll('input').forEach(i=>i.oninput=draw);draw();}

