/* ---- L0 основы ---- */
RULE(0,'Как найти количество вещества, если известна его масса?','n = m / M',['n = m · M','n = M / m','n = m / 22,4'],
{short:'n = m/M: граммы делим на граммы на моль.',explain:'Количество вещества n = m / M, где M — молярная масса (г/моль). Единицы: г : (г/моль) = моль ✔ Формула n = m/22,4 — ошибка: 22,4 л/моль относится к <b>объёму газа</b>, а не к массе.',
explain2:'Как пачки: 30 конфет по 5 в пачке — это 30/5 = 6 пачек. Масса / масса одного «моля» = число молей.'});
RULE(0,'Что показывают коэффициенты в уравнении реакции?','Соотношение количеств веществ (моль) — и объёмов газов',['Соотношение масс веществ в граммах','Число атомов в одной молекуле','Молярные массы веществ'],
{short:'2H₂ + O₂ → 2H₂O: 2 моль : 1 моль : 2 моль, а не 2 г : 1 г : 2 г.',explain:`Коэффициенты считают частицы, а значит и моли: в ${EQ(RX.h2o)} на 2 моль H₂ нужен 1 моль O₂. По массе это 4 г и 32 г — совсем не 2 : 1! Число атомов в молекуле показывают <b>индексы</b>, а не коэффициенты.`,
explain2:'Рецепт «2 яйца на 1 стакан муки» — это штуки и стаканы, а не граммы. Коэффициенты — такой же рецепт в «штуках» (молях).'});
G(0,()=>{const rx=RX[pick(['al','zn','kmno4','h2o','p','ch4','nh3','domna','kclo3','na','cuoh'])];const all=[...rx.L,...rx.R];const [a,b]=sample(all,2);const na=pick(NS);const ka=K(rx,a),kb=K(rx,b);const nb=na*kb/ka;
 return NUM(`По уравнению ${EQ(rx)}: сколько моль ${C(b)} ${rx.L.includes(b)?'нужно (вступит в реакцию)':'образуется'}, если ${rx.L.includes(a)?'в реакцию вступило':'образовалось'} ${N(na)} моль ${C(a)}?`,nb,2,
 {short:`n(${C(b)}) = ${N(na)} · ${kb}/${ka} = ${N(rd(nb,3))} моль.`,
 explain:`Коэффициенты: перед ${C(a)} — ${ka}, перед ${C(b)} — ${kb}. Значит, n(${C(a)}) : n(${C(b)}) = ${ka} : ${kb}.<br>n(${C(b)}) = ${N(na)} · ${kb} / ${ka} = <b>${N(rd(nb,3))} моль</b>.`,
 explain2:`Пропорция: по уравнению ${ka} моль ${C(a)} — ${kb} моль ${C(b)}; у нас ${N(na)} моль ${C(a)} — x. x = ${N(na)} · ${kb} / ${ka} = ${N(rd(nb,3))}. ${ka===kb?'Коэффициенты равны — и моли равны.':''}`});});
G(0,()=>{const rx=RX[pick(['al','h2o','p','kmno4','ch4','nh3','domna','mgo','kclo3','h2so4'])];const [a,b]=sample([...rx.L,...rx.R].filter(f=>f!=='H2O'||rx===RX.h2o),2);const ka=K(rx,a),kb=K(rx,b);const g=H.gcd(ka,kb);
 const corr=`${ka/g} : ${kb/g}`;const mr=`${N(Mr(a)*ka)} : ${N(Mr(b)*kb)}`;const wr=[`${kb/g} : ${ka/g}`,'1 : 1',`${parseF(a)[Object.keys(parseF(a))[0]]} : ${parseF(b)[Object.keys(parseF(b))[0]]}`,`${ka/g+1} : ${kb/g}`];
 const W=[...new Set(wr)].filter(x=>x!==corr).slice(0,3);if(W.length<3)return null;
 return CH(`В реакции ${EQ(rx)} в каком отношении находятся количества веществ n(${C(a)}) : n(${C(b)})?`,corr,W,{short:`Как коэффициенты: ${ka} : ${kb} = ${corr}.`,
 explain:`Количества веществ относятся как коэффициенты: перед ${C(a)} стоит ${ka}, перед ${C(b)} — ${kb}. n(${C(a)}) : n(${C(b)}) = ${ka} : ${kb}${g>1?` = ${corr}`:''}.<br>А массы относятся иначе: ${ka}·${N(Mr(a))} : ${kb}·${N(Mr(b))} = ${mr}.`,
 explain2:'Индексы внутри формулы (маленькие цифры) — про состав одной молекулы. Отношение молей в реакции дают только большие цифры перед формулами.'});});

